import sqlite3
import hashlib
import hmac
import os
import re
import secrets
from typing import Optional, Dict, Any
from dataclasses import dataclass
from enum import Enum

DB_PATH = os.environ.get('DB_PATH', '/var/app/data/app.db')
SECRET_KEY = os.environ.get('APP_SECRET')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET environment variable required')

class ResourceType(Enum):
    POSTS = 'posts'
    COMMENTS = 'comments'
    MESSAGES = 'messages'
    AUDIT_LOG = 'audit_log'

# Allowed sort columns per resource type - prevents SQL injection in ORDER BY
ALLOWED_SORT_COLUMNS: Dict[str, list] = {
    'posts': ['id', 'created_at', 'title', 'author_id', 'updated_at'],
    'comments': ['id', 'created_at', 'author_id', 'post_id'],
    'messages': ['id', 'created_at', 'sender_id', 'recipient_id'],
    'audit_log': ['id', 'timestamp', 'actor_id', 'action'],
}

# Table name mapping - maps resource identifiers to actual table names
TABLE_MAPPING: Dict[str, str] = {
    'posts': 'user_posts',
    'comments': 'post_comments',
    'messages': 'direct_messages',
    'audit_log': 'system_audit_log',
}

@dataclass
class AuthToken:
    user_id: int
    session_id: str
    is_admin: bool

def _verify_auth_token(token: str) -> Optional[AuthToken]:
    """Verify HMAC-signed auth token."""
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return None
        payload_hex, sig_hex = parts
        expected_sig = hmac.new(
            SECRET_KEY.encode(),
            bytes.fromhex(payload_hex),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expected_sig, sig_hex):
            return None
        payload = bytes.fromhex(payload_hex).decode()
        fields = payload.split(':')
        if len(fields) != 3:
            return None
        return AuthToken(
            user_id=int(fields[0]),
            session_id=fields[1],
            is_admin=fields[2] == '1'
        )
    except (ValueError, TypeError):
        return None

def _get_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA journal_mode=WAL')
    return conn

def _validate_resource_type(resource: str) -> bool:
    """Validate resource type against enum values."""
    try:
        ResourceType(resource)
        return True
    except ValueError:
        return False

def _resolve_table_name(resource: str) -> Optional[str]:
    """Resolve resource identifier to actual table name.
    Only allows explicitly mapped table names.
    """
    return TABLE_MAPPING.get(resource)

def _validate_sort_column(resource: str, column: str) -> bool:
    """Validate sort column against allowlist for the resource."""
    allowed = ALLOWED_SORT_COLUMNS.get(resource, [])
    return column in allowed

def _build_filter_clause(filters: Dict[str, Any]) -> tuple:
    """Build parameterized WHERE clause from filters."""
    if not filters:
        return ('1=1', [])
    clauses = []
    params = []
    for key, value in filters.items():
        # Only allow alphanumeric column names
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', key):
            continue
        clauses.append(f'{key} = ?')
        params.append(value)
    if not clauses:
        return ('1=1', [])
    return (' AND '.join(clauses), params)

def query_resources(
    token: str,
    resource: str,
    filters: Optional[Dict[str, Any]] = None,
    sort_by: str = 'id',
    sort_order: str = 'ASC',
    limit: int = 50,
    offset: int = 0
) -> Dict[str, Any]:
    """Query resources with authentication, authorization, and input validation."""
    # Authentication
    auth = _verify_auth_token(token)
    if auth is None:
        return {'error': 'Authentication failed', 'status': 401}

    # Validate resource type
    if not _validate_resource_type(resource):
        return {'error': 'Invalid resource type', 'status': 400}

    # Resolve table name
    table_name = _resolve_table_name(resource)
    if table_name is None:
        return {'error': 'Resource not found', 'status': 404}

    # Validate sort parameters
    if sort_order.upper() not in ('ASC', 'DESC'):
        sort_order = 'ASC'
    else:
        sort_order = sort_order.upper()

    if not _validate_sort_column(resource, sort_by):
        sort_by = 'id'

    # Validate pagination
    limit = max(1, min(int(limit), 100))
    offset = max(0, int(offset))

    # Build filter clause
    where_clause, params = _build_filter_clause(filters or {})

    # Authorization: non-admin users can only see their own resources
    if not auth.is_admin:
        if resource in ('posts', 'comments'):
            where_clause += ' AND author_id = ?'
            params.append(auth.user_id)
        elif resource == 'messages':
            where_clause += ' AND (sender_id = ? OR recipient_id = ?)'
            params.extend([auth.user_id, auth.user_id])
        elif resource == 'audit_log':
            return {'error': 'Forbidden', 'status': 403}

    # Build and execute query
    query = f'SELECT * FROM {table_name} WHERE {where_clause} ORDER BY {sort_by} {sort_order} LIMIT ? OFFSET ?'
    params.extend([limit, offset])

    try:
        conn = _get_connection()
        cursor = conn.execute(query, params)
        rows = [dict(row) for row in cursor.fetchall()]
        conn.close()
        return {'data': rows, 'status': 200, 'count': len(rows)}
    except sqlite3.Error as e:
        return {'error': 'Database error', 'status': 500}

def delete_resource(token: str, resource: str, resource_id: int) -> Dict[str, Any]:
    """Delete a specific resource by ID."""
    auth = _verify_auth_token(token)
    if auth is None:
        return {'error': 'Authentication failed', 'status': 401}

    if not _validate_resource_type(resource):
        return {'error': 'Invalid resource type', 'status': 400}

    table_name = _resolve_table_name(resource)
    if table_name is None:
        return {'error': 'Resource not found', 'status': 404}

    if not auth.is_admin:
        return {'error': 'Forbidden', 'status': 403}

    try:
        conn = _get_connection()
        conn.execute(f'DELETE FROM {table_name} WHERE id = ?', (int(resource_id),))
        conn.commit()
        conn.close()
        return {'status': 200, 'message': 'Deleted'}
    except sqlite3.Error:
        return {'error': 'Database error', 'status': 500}
